) AS (
  VALUES 
    (433::BIGINT, 'vayan los miércoles anda mas contenta ;D'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-08-21T00:00:00+00:00'::TIMESTAMPTZ, '379ef4f7e4f5beb93f340e61dbb3ca2ea2405b1d05e7693ab463dde4db3d5ce5'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'La profesora es buena gente con los estudiantes, es amigable, hace conversación, hace comentarios graciosos, el problema es que para explicar no es clara, se enreda dando su propia materia, en los exámenes presenta ejercicios que no llegan a ser muy claros'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'c19e997a2984d0ec28f9699c6a734ca172f80fa921bcae5515a450ca96f7b61f'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'La profe es muy buena persona, si uno le pide ayuda en clase ella ayuda. Califica muy duro ella y los asistentes, sus exámenes son muy difíciles y no ayuda mucho a la preparación de estos porque no deja practicas correctas o ejemplos en clase. Se vuelve un curso PESADO, hay que meterle a los labs.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2026-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'b196fa7b8e0ed83de694c396a407b2fc4c8bad0cadd00686a8e2bab05e3c6088'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Es increíble como la profe caiga tan bien, explique tan mal y califique como si le debiera pensión. El problema surge en que explicando se enreda mucho y calificando te castiga con severidad si te equivocas, además de que los exámenes son sencillos pero confusos a la vez.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico']::TEXT[], '2026-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'aaed3f83639fbd7b0bd4f27862f0e609d627d8c78308b67c316b42dda11fb67a'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'Es buena gente y busca ayuda. Sin embargo, no es el clara, suele enredarse y cuesta mucho seguirla con la explicación. En los temas de probabilidad suelen salir ejercicios que no vemos en clase. Sale mucho de clase a hablar con otros profes y usa demasiado el celular.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores']::TEXT[], '2026-07-09T00:00:00+00:00'::TIMESTAMPTZ, 'be8a53238a8c2586a24776c1aed6496b16f24fdb6cd4990d49a6ca4293cd5935'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'No es terrible pero tampoco excelente. Se enreda con sus propios ejemplos (se enreda mucho y en todas las clases). No es demostrativa. Las presentaciones no son cómodas para estudiarlas. Estudie mucho por aparte, YT me salvó. Algo bueno es que siempre brinda ayuda si se la pide.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2026-07-05T00:00:00+00:00'::TIMESTAMPTZ, '8a0c0f7ef978f15490ca611cd429b8985ec7c26fcac5f339174dfc117111a534'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'Ella sabe mucho y explica claro, solo que evalúa muy tryhard, entonces cuesta mucho en los exámenes, porque la materia es bien pesada y hay que seguir las presentaciones al pide la letra. Hay que ponerle demasiado para pasar y pasar apenas. Es muy duro con ella.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '09f1a0ee40c8c6eb0ea42083254059588c16de8f9a25638239fdbe3ad83137f9'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Se aprende pero hay que llevar la materia al día y poner cuidado. Las presentaciones vienen con errores. . Si consigue cosas viejas ayuda mucho. Busque buen grupo para el proyecto. Muy accesible para dudas pero a veces es grosera al responder. Si muestra interés ella lo ayuda'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2026-01-11T00:00:00+00:00'::TIMESTAMPTZ, '38ffebb70cba8e53146f7e921a1b344a2f0d13ce8f8ba65666c1a642e3d5f9b7'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'No califica bien, inventa soluciones y hace sentir menos a los estudiantes. Siempre tiene favoritos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-12-22T00:00:00+00:00'::TIMESTAMPTZ, 'b4282a37445f46144771aa78cb3b716f565a0847d7e3beb3ffbe6a748d126e38'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Se preocupa más por caerle bien a los estudiantes que por dar la materia. No terminamos de ver la materia completa, la materia no es muy complicada y no explica tan mal, pero si tiene la oportunidad de matricular con otro, sería lo mejor'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'f7a68b699dea73f62b40f048c85e765e51750bf366072c0f1922c709b69ae3ef'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'Con ella va a aprender, pero las evaluaciones no tienen ningún sentido, se inventa cosas y revisa como le da la gana. Es un curso fácil que ella lo hace muy tedioso y le gusta ver sufrir a la gente. Puede meterlo y va a aprender, pero va a batallar de fijo con ella.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, '7486b9ae5e65d4a1a790b9d0dbe49b030558a9ce8efca43abd89e5a330f1dfc2'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Honestamente con la profe si se aprende bastante, unicamente por lo menos para Estudio II el curso si se vuelve bastante autodidacta ya que la profe no manda prácticas de los temas evaluados, entonces uno depende mucho de las evaluaciones de semestres anteriores. El curso se pasa.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, '89c53e771bba6dc3c794d01bc216ece857de20de40d1c6c35eb60057d2846d53'::TEXT, ARRAY[1736]::BIGINT[]),
    (433::BIGINT, 'La profe en si es buena gente, respetuosa, los cursos si son un poco duros así como las calificaciones, pero normal para un curso del TEC, nada del otro mundo con estudiar y hacer los trabajos se pasa.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '3945439401c538b128a19f127d861288272f8db5c0ba494c6e9ab0946d8e7f85'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'En la clase no se entiende nada, quiz cada 15 días, deja tareas y eso es lo que pone en el quiz, Revisen los puntos de todo, porque no suma bien, o pone errores donde no los hay.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos exámenes']::TEXT[], '2025-07-17T00:00:00+00:00'::TIMESTAMPTZ, '94797bed282348c4984096c20d15ac6c5f75ff0a502b50693e331022ac20a759'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'Explica regular, los quiz y exámenes están llenos de trampas, y luego tienen errores de revisión, así que revise las evaluaciones, en general no es la mejor, pero se la juega'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-06-30T00:00:00+00:00'::TIMESTAMPTZ, '907df301e8d4b5dd7406c26a12b5afb3022864fa9ae02d1a7c30a24d58ffe1e1'::TEXT, ARRAY[1736]::BIGINT[]),
    (433::BIGINT, 'Si quiere aprender, definitivamente matricule con ella. Es un poco distraída y tiende a hacer comentarios "subidos de tono" o "pasados", pero es buena profesora. Les recomiendo que se hagan de un excelente grupo de trabajo, ya que la mayoría de las evaluaciones son grupales.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2025-04-14T00:00:00+00:00'::TIMESTAMPTZ, 'd62b7c43c8f43ebec922876c8fe812c64c68a13d228fbe1e9ef1efe2bc90df11'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'A la profe no le gustan estudiantes mediocres, prepárese para leer, vaya a consulta, participe en clase y no se tome personal los comentarios que ella hace, suele decir cosas extrañas o referirse a los estudiantes pero no es nada personal al final'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, '06de6b72b1b6e54ab02ced1f223c37fa98b3e1713b29f55b487b9bbcb97bb0b7'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Ella tiene mucha experiencia y conocimiento, se aprende bastante. Sí es posible pasar, solo que hay que morderse con el estudio, e ir a consulta, pida exámenes viejos. Su personalidad es cruda, hay que saber tratarla REVISE LOS PUNTOS DE LOS EXAMENES y reclame con firmeza, siempre se le van detalles'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'a4a25e16b4522f747bd1a51b72384ec1e942b5114c3b842d98a5d0a42817e9e8'::TEXT, ARRAY[1736]::BIGINT[]),
    (433::BIGINT, 'Material de estudio incorrecto con conceptos y ecuaciones incorrectas, ejercicios mal resueltos y cambia de notación a cada rato, NO se puede estudiar con el material de estudio. Evaluaciones extra complicadas, confusas, sin instrucciones o evaluaciones claras.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2024-11-09T00:00:00+00:00'::TIMESTAMPTZ, 'f414d0dd54d2e3e8e7c6c190159d23c7d5d88230f84e4ac6b3fb906b7d74652e'::TEXT, ARRAY[963, 1728]::BIGINT[]),
    (433::BIGINT, 'El curso con ella requiere de mucha práctica por aparte y que vaya a consultas. Los exámenes son más complicados que lo que se ve en clase, pero no es imposible pasar el curso.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'f71cdd1496a3d8f5c4c474f02eb5910d21926b504c14880b8ffe0aaac1f3b470'::TEXT, ARRAY[963, 1728]::BIGINT[]),
    (433::BIGINT, 'Si su propósito es aprender, con ella lo hará. Si quiere pasar, lleve con Liss. Sus exámenes son casi imposibles (a menos de que usted dedique su vida a probabilidad y estadística), además de que penaliza durísimo. Ella dice que menos del 40% de sus estudiantes pasan; en realidad es mucho menos.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '5b738a5b03d4aaee3676cb4ba1824400ccd909ccce116bf0bcefebcacd785b30'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Es una persona que parece que no quiere trabajar, todo lo hace sin ganas,siempre culpa al estudiante. Manda práctica, y no hay respuestas, ni le da la gana ver por encima algún ejercicio que uno hizo. Para reclamos se cierra, busca humillar. Su material de clase tiene muchos errores, no se entiende'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2024-05-30T00:00:00+00:00'::TIMESTAMPTZ, '699dfbda60c24d593c1c1de00a073d54a962a62afae75c08ba65b06f02086cc8'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Actualmente estoy cursando el curso con ella y me sorprende de verdad lo pésima profesora que es, matriculen con Liss, explica con una presentación llena de errores de hace 13 años, no se sabe la materia, a cada rato se distrae con mensajes y abandona la clase y evalúa temas que ni explica en clase.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2024-03-08T00:00:00+00:00'::TIMESTAMPTZ, 'b12073587d55e22043407b30c19489568f794fb8fbe46de98ebfe0de5d4f8267'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'd9effb91f8c4ec44dea6d36cdaa231a603c09dcd84ddbb4797828f379cfbd81a'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Verdaderamente es un asco de persona y de profesora. Pasé su curso, pero sufrí demasiado y ella de verdad se ve que disfruta humillar gente.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2024-01-19T00:00:00+00:00'::TIMESTAMPTZ, '0acb6486ef46d9c797726870a63f7d389d411ad44c5d0b3820561e115af38b47'::TEXT, ARRAY[1446]::BIGINT[]),
    (433::BIGINT, 'Terrible profe no le importa que el estudiante aprenda, mete cosas que no se ven en clase'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-09T00:00:00+00:00'::TIMESTAMPTZ, '0b6f393b6bc0a3a67293568cb4d7c384c668ca6da15fc7d05a23e34e58f6a42b'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'La profe explica excelente y bastante claro, todos los trabajos son en grupo y demasiado largos y verdaderamente se tiene que tener un orden con ellos, sino no los van a sacar. Los examenes son bastantes duras, pero con que usted se siente a estudiar y comprender le va air bien. La recomiendo'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, '479fafa241713b6ed0baf911ec6a4b5aeccea9f305ffbe7eb0ac5fe6bd8a2043'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Se aprende todos los temas del curso completamente. No por que explique bien si no por que va a tener que hacerlo para pasar el curso. Los exámenes no son tan difíciles, lo que vuelve el curso muy difícil es que califica en binario todo. Curso muy difícil con ella, ahórrese el sufrimiento'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'c86639c0c50be813b002b05135c4719430d3d043191c4dd4341462760c62f138'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Todo los comentarios son verdad. Explica super bien y la verdad uno aprende, sin embargo, la dificultad que ella maneja en las practicas o ejemplos que da en clase no son iguales a los examenes. No ayuda al estudiante, es buena persona pero como profe no. No la recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, '1e66a528f5efe10b2d871a8857e1141e69bc0760774be1a8418640d30b070a02'::TEXT, ARRAY[1736, 1727]::BIGINT[]),
    (433::BIGINT, 'Excelente profesora, nose porque tiene tan malos comentarios, ella es solo estricta y es excelente profesora explica muy bien y se aprende bastante. En logística es la mejor opción.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'cdd45a10c00363de104d8857adafbd8d554153d6173f29939c5227760f1feb8d'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Ella misma dice que quiere pensionarse ya mismo porque no soporta más dar clases. Durante quices y exámenes e incluso dando clases suele contestar llamadas y mensajes. Se confunde a la hora de realizar ejercicios y en los exámenes hasta pone ejercicios sin respuesta o de cosas que ni vimos en clase.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '73b16171817814f78e13199d85d30cc1d437320e2b01225db9201c0e6f429d81'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'En clase se guía con las diapositivas, cuando hace ejercicios sin estas comete errores constantemente, lo cual confunde bastante. Algunos ejercicios que tiene resueltos en las diapositivas no responden lo que pide el enunciado.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'd179755ac6aeb7a9705b8bcc30d97b653e2abbb48eb8800b9f5d452d8e0064d9'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Es buena profesora, se guía en las diapositivas y presentaciones para dar la clase, si usted pregunta le aclara las dudas. Los quinces son variados unos difíciles y otros fáciles y los exámenes son pesadillos pero pasables.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '754574e434842e4309bf6e1a0e7f8c02afd1d25d17bbcee9673988f0a69c767f'::TEXT, ARRAY[963, 1728]::BIGINT[]),
    (433::BIGINT, 'Una profesora desagradable, no sabe otra cosa además de leer las diapositivas. No explica bien y bajo la excusa de "A los estudiantes se les da la mano y agarran el brazo" busca la manera de ser lo más irritante posible'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2023-06-09T00:00:00+00:00'::TIMESTAMPTZ, '0f91e50d5fe174f22548f0ae8739ba9fe5b6212521acfeb1fa46f380ee0ebe41'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Si de verdad quieres aprender, matricule con ella en Estudio del Trabajo I,explica bien,hace muchas dinámicas en clase que ayudan montones a dominar la materia y los objetivos del curso,sean ordenados con tiempo para los informes y lleven todo al día porque si no se vuelve tedioso.(es estricta)'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-16T00:00:00+00:00'::TIMESTAMPTZ, 'b0249018c26d8e4d0e618bbcbc47a62af5851f062deb6a797570e0b0d509bf4d'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Como persona es amable, como profesora diría que regular, el principal defecto es que entre lo que se ve en clase y lo que califica en los exámenes existe en algunos casos mucha diferencia de dificultad. Lo más aconsejable es conseguir pruebas pasadas. Califica entre normal o duro'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-21T00:00:00+00:00'::TIMESTAMPTZ, '2b16e29623a973078a2011799dd4eb83736be8507ca8c52dfcd3deb3ab528e2e'::TEXT, ARRAY[1745]::BIGINT[]),
    (433::BIGINT, 'Para este curso es muy exigente pero en verdad se aprende con ella, debe tener mucho orden con respecto a la entrega de los laboratorios y no dejarlos para último momento puesto que son muy extensos'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-12-04T00:00:00+00:00'::TIMESTAMPTZ, '7058a0af4dc851791ecc6f3b5af720e1a958a03ab3d0f1b30817b19a91e4a98d'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Lo mejor es estudiar con evaluaciones de semestres pasados por que lo que se ve en clase es mas facil. En general explica bien y es buena gente'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-27T00:00:00+00:00'::TIMESTAMPTZ, '73403aaec2c8915b0da4474724fd8f62edde6e58251d0cc10206c74b867cfbdf'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Estudie con exámenes viejos, repite los ejercicios!!! El proyecto es hacer un erp que califica muy suave. En este curso no es tan mala como en los otros. Hay temas que no los explica muy bien pero si uno le pregunta, explica con amabilidad. Durante los exámenes ayuda bastante y atiende dudas.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-22T00:00:00+00:00'::TIMESTAMPTZ, '36e29c43d9c7069ac719312d3b6ebdb4de593ca57f660f71a5a2f33ccaa3a598'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'La profe es una carepi como persona, pero el curso es pasable y repite las evaluaciones de otros semestres.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2022-11-22T00:00:00+00:00'::TIMESTAMPTZ, '99710c7d3406bdeb38a899263bc4c9487fe418a1709d8a6771449782f9b19f7e'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Es una buena profe para este curso, se aprende con ella, los quices y exámenes son iguales a los de semestres anteriores. Califica suave pero a veces un poco duro. La recomiendo en este curso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-19T00:00:00+00:00'::TIMESTAMPTZ, '61b39a1e4c1035a825113488c7e1f166b97408b2e08d7cf584b04ae5a3df171f'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Para este curso no es mala, califica duro pero no es imposible de pasar. De vez en cuando tiene sus momentos de ser medio repugnante con los estudiantes, pero desde mi experiencia algo relativamente normal.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2022-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'fb2d109393c4761191e257fde0caf94bb677dbce08f6d667776e17cbe562b9d4'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Explica bien, pero el nivel de los exámenes es mucho mayor a lo que se hace en clases. Preferiblemente practicar con exámenes viejos'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'e3218ca396f392186cf7dcb33ca9e573b5c8e4628a4388f661d21a7f81e967d2'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Explica bien, pero procure no quedarse con lo que se ve en clase. Califica un poco rudo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-15T00:00:00+00:00'::TIMESTAMPTZ, '68c97329068f7dade57f9cfe1b767e83c918e04eb91e78719dbd0f2124837283'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'No podría conocer profesora más vagabunda y odiosa que existe. Verdaderamente lo poco que tiene de profesional, lo tiene a la mitad en empática. Si solo ella da una materia alguna vez, les recomiendo cambiar de carrera porque no es sano toparse con persona tan incómoda para la vida'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2022-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'fb7e3e02f0492537ed6ced99a95ee009ef71435758c608fa5ca1e831b35c376f'::TEXT, ARRAY[1736]::BIGINT[]),
    (433::BIGINT, 'Me atrevería a decir que a esta profesora la maltrataron de alguna forma en algún momento, porque el nivel de mala persona que es, parece mentira. Es como Umbridge, la de Harry Potter, y con eso les digo todo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'd4962fdfd6f8c948748b5d6509cc0e1c1fbff0a0e6b57d97ad6e8722814bf677'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'Ella es buena persona pero no le va a regalar ni medio punto, consiga un buen grupo de trabajo para los casos y le va a ir bien. Los exámenes son difíciles y los califica duro. Explica bien aunque puede ser un poco aburrida.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '295e36e7e478b5e852cfc7e30f423efb36bc93fe5122ed9e30c99145b00692c5'::TEXT, ARRAY[1736]::BIGINT[]),
    (433::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '70c8e29f5bbbae4c88b524c0c838cd8db6c083635232a24987c8b2e98d4c24b6'::TEXT, ARRAY[1736]::BIGINT[]),
    (433::BIGINT, 'Para las evaluaciones hay que estudiar mucho, tenga cuidado en ocasiones tiene mal las soluciones del examen y pierden puntos injustamente, hacer los reclamos en los tres días hábiles porque luego no acepta. Los ejercicios que hacen en clases son muy sencillos en comparación a los quices y exámenes.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '202474da017da9d0295f326a799cf7219d59f916ae6b92518a75050d758151f1'::TEXT, ARRAY[1446]::BIGINT[]),
    (433::BIGINT, 'SIEMPRE revisen bien sus exámenes. Ella los revisa muy mal.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'f9c6e688eccc91f17450963b349f0dc00c444d16db942b87acfaa3996ee9d910'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'Es la peor profe que he tenido. Si sabe mucho pero la forma en la que enseña no es nada buena, es muy grosera, no acepta reclamos. Se aprende pero en los exámenes y quizes todo tiene que ser a como ella lo hace, no es nada flexible y califica muy duro.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'd8b3470be73ed63ec79af13bc522e1a3ed0058df134bd54dbaa718237af4fd90'::TEXT, ARRAY[1736]::BIGINT[]),
    (433::BIGINT, 'No la recomiendo!! ... Los ejercicios los saca del libro Miller... Y si uno le pregunta algo más avanzado lo evade ! Es buena gente pero puede hacerle la vida de cuadritos a cualquiera!'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'ef1ad1c192633bfc88c0de255b24f36d8c5ba434f48af3a7e5bc3a37ad9d170c'::TEXT, ARRAY[963, 1728]::BIGINT[]),
    (433::BIGINT, 'La profesora es buena gente si se le trata con el debido respeto y profesionalismo, hay que repasar bastante ya que en su mayoría los ejercicios no quedan claros, tiene el corazón frio, no le duele quedar a un estudiante independientemente de su situación.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '39b1aa814eb0523a61d38434a6717918228077e28e101d742648bdfa342d6ea5'::TEXT, ARRAY[1446]::BIGINT[]),
    (433::BIGINT, 'En este curso la profe es buena, explica mucho la material y da muchos ejemplos, eso sí se solía equivocarse en las evaluaciones y le faltaban datos , también puede equivocarse calificando entonces tener cuidado de revisar porque les puede poner una nota menor, sin embargo, se APRENDE BASTANTE.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '95d3c8a43dc46fa5972c2363f4e2d87cbe82a534fb1336da32ad0a3d794e2d71'::TEXT, ARRAY[2474, 1745]::BIGINT[]),
    (433::BIGINT, 'En esta electiva es normal, explica bien, la clase no es fea, solo que parece que prepara el quiz media hora antes de la clase, o sea, faltan la mitad de los datos para hacerlo y es poco clara en las indicaciones Igual el curso no es pesado ni complicado, la materia es super chiva'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-10T00:00:00+00:00'::TIMESTAMPTZ, '4d7388ffe8bbfbda06b2558bef5d78857b9e3e76b93df904ff4c5fb32df0864e'::TEXT, ARRAY[1774]::BIGINT[]),
    (433::BIGINT, 'Ella es un amor de persona pero a la hora de recibir críticas o demás se hace la loca y básicamente le echa la culpa a uno, cuando la culpa la tiene ella por lo general y no se hace responsable y uno es el que sale perdiendo con los puntos'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-27T00:00:00+00:00'::TIMESTAMPTZ, 'e74033d533b6e62a67f770b11c4d901770cbe5b3d7946693780e7512dcf6178f'::TEXT, ARRAY[1774]::BIGINT[]),
    (433::BIGINT, 'Evaluaciones muy largas y poco pedagógicas, califica puro formato y MUY rudo, en clase dice algo y califica otra No le gusta atender correos y la consulta es muy difícil de acceder . Siempre se va por la tangente en clases, no concretiza y solo habla de su vida personal no relevante con la carrera'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, '23106838085ca14570d45665d7d12715374a003cec7f1e5712a9a2f5d4795aa2'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Si quiere aprender lleve con ella. La profe podrá ser estricta pero explica super bien y está demasiado dispuesta a ayudarlo a entender. Los trabajos sí son bastante largos y los exámenes son lo que se ve en clase (fáciles). Con los trabajos si el grupo se lo pide puede dar 2 o 3 días más.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'efd47eef443a7ad4632555290b010c8f26103b62961e08f79f9967deb7f03832'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Buena profe, explica bien y es un amor con los estudiantes. Sin embargo, califica muy duro y deja trabajos muy largos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'f7efcd14552e7fdcc43b70e340a91fb9c086475e63fbe2937d025ed8ef2facdf'::TEXT, ARRAY[1736, 1727]::BIGINT[]),
    (433::BIGINT, 'Es una excelente profesora, muchos no la quieren porque es estricta en sus evaluaciones, pero se aprende muchísimo.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'db5b0a572b305ed536f22ae8706bf44bc526784abab3e404afc3dea85e62687b'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'La señora es muy amable dando clases, pero se equivoca mucho haciendo los ejemplos e incluso revisando. Si van a matricular con ella REVISEN BIEN SUS EXÁMENES por que al rato les dan menor nota de la que se merecen y terminan palmando el curso. Ella no acepta reclamos luego de los 3 días hábiles.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos exámenes']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c5b5e2cd87f40120c9e241471aac216f58d9ae3959671bfe5fe5cf03b4b3bfe8'::TEXT, ARRAY[1446]::BIGINT[]),
    (433::BIGINT, 'Es una excelente profesora y se nota que también una excelente persona. Es MUY estricta, sigue las reglas tal y como son pero adicional a ello te va a enseñar para LA VIDA y adicional para tu formación académica. No me arrepiento de haber llevado Estudio del Trabajo 1 con ella aunque fuera pesado.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2021-06-17T00:00:00+00:00'::TIMESTAMPTZ, '01644d5892f1e553b82d44758d96379b1c98dde8b74036b1fc9ffca4ae6b2605'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Trate de EVITAR matricular con ella al máximo, es cero comprensiva, da poco tiempo en los examenes y quices y sobre todo al explicar se enreda mucho'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2021-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'b40528cec501596c7a1c0658a6b177ee24041897c8f066fed3c75babb4be0f4f'::TEXT, ARRAY[1446]::BIGINT[]),
    (433::BIGINT, 'Hay que ponerle mucho, es exigente pero llevadera. Le gusta que los trabajos esten bien hechos, el curso es pesado pero si le pone lo pasa bien'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-13T00:00:00+00:00'::TIMESTAMPTZ, '4d4146c235586b39f3ac97a0e22e6ef578543623a98ad05d0d10d9f784eadd04'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'En este es más relajada, enseña bien, pongan atención a los detalles que por ahí está la solución a los exámenes, buenos ejemplos, y pregunten siempre "y que pasa si..?" para que no los sorprenda en el examen, se aprende bien'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '5ac4a4a0bcd56f024cfe95b1d64b7620dae6d7ac8f3324d38628a674bf3e8b67'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'A ella muchos no la quieren porque califica bastante duro, pero es una excelente profesora, lo que explica se le entiende bastante claro y de no ser así repite lo necesario, da muchos ejemplos, aunque casi siempre tienen que ver con la maquila o walmart jaja pero es una excelente profe'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-05-14T00:00:00+00:00'::TIMESTAMPTZ, '6f0f05f42a7b064df92417ad60c6dd638daef3f7fc045cf742af42dc8f1a934c'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Ella pretende que es la mejor profesora del tec pero es un asco de persona. Me esta jodiendo? Ella como puede estar dando clases?'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-03-06T00:00:00+00:00'::TIMESTAMPTZ, 'c57bf86333e5052fd8379dfe3da52d36f6965da3c9186a0caacf642ef783e2a9'::TEXT, ARRAY[1446]::BIGINT[]),
    (433::BIGINT, 'La profesora da clases que enredan la mayoria de veces. Si uno trata de pasar el curso solo con la profesora se queda, uno debe de ponerle demasiado. Actitud irresponsable y desconsiderada de parte de la profesora. No matriculen porque le daran el gusto de que los haga sufrir.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Exámenes retadores']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '23441886c76e4aba30dec2c8a4e2d42791bec70e2a574a3dc0fb8e2e268b4865'::TEXT, ARRAY[1446]::BIGINT[]),
    (433::BIGINT, 'la peor profesora que he tenido en el TEC. es demasiado desconsiderada, no se preocupa por los estudiantes ni trata de ayudarlos, siempre se equivoca dando la materia. no hay una cosa positiva que pueda decir de ella, arruinó por completo mi experiencia en este curso y jamás la recomendaría'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'cdb05b4a76031099ab11289b08ff6dfaf3cfd4b50aaa9e5a02adb2c15027997c'::TEXT, ARRAY[1446]::BIGINT[]),
    (433::BIGINT, 'Una profesora que demuestra que no asume responsabilidades y se excusa en sus superiores y situaciones que no tienen relevancia en el curso. Parece que para ella no pueden existir problemas con el internet ni con la forma en que da el curso. La verdad es lo peor que he encontrado en el TEC.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, '7cc91b7582a3f8e49125bf5b136d712d047ad2e4ea2159ba2675858d9dd231db'::TEXT, ARRAY[1446]::BIGINT[]),
    (433::BIGINT, 'es la peor profesora del tec y se esfuerza porque los estudiantes se queden, no da tiempo suficiente en los examenes, ella siempre tiene la razón, califica durísimo y no explica para nada bien, NUNCA matriculen con ella, aunque sea la única opción, mejor esperar a otro semestre que no sea ella'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'a2feb1b73d2f3a568134933d3a3f4018c5cc521bd6807a25de994c919badf4c4'::TEXT, ARRAY[1446]::BIGINT[]),
    (433::BIGINT, 'PÉSIMA, nunca matriculen con ella... Objetivo principal como profesora: “Que todos los estudiantes se queden” “Exime” porque sabe que ningún estudiante se ha podido eximir con ella... Si desean pasar a la primera NO matriculen con ella, es la PEOR... no se aprende nada...'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2020-12-16T00:00:00+00:00'::TIMESTAMPTZ, '31a75c47711c4a533e05bebe32c8178c54674a8f34684477057e3172333a98b6'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'Muy confuso como explica, y se equivoca mil veces. No ayuda en nada, y pone excusas para no ayudarle a uno. Los exámenes son difíciles y no da mucho tiempo. No la recomiendo para nada.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2020-12-15T00:00:00+00:00'::TIMESTAMPTZ, '3b1f4737ed23190aed86b02a88072182ea88c5ee622d3e59319bd9adc150ce3c'::TEXT, ARRAY[1446]::BIGINT[]),
    (433::BIGINT, 'Como profesora es excelente, sabe demasiado y de verdad que se aprende, el problema es que hay veces se enreda un poco y los examenes son dificiles. Si estudia bastante pasa, no te va a regalar el curso.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'f24a915a21aaa1ffa0f3a6caa10fcd857a8591583200d9d08eb8a56c39a5dae5'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'lleve el curso virtual,como persona muy buena y correcta, como profe explica bien pero le queda faltando un poco,califica un poco duro y las clases son cansadas,los ejercicios de exámenes son de libro o recursos que uno puede tener a mano'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Muchos exámenes']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'c1f5fe64655015dacf3bdfe102f099d5187acde4e3fef48cbd1f54fca4a878dc'::TEXT, ARRAY[1728, 1742, 1743]::BIGINT[]),
    (433::BIGINT, 'La profe es muy buena persona. Sin embargo, como profesora sus clases son un poco confusas cuando explica la materia, y todo lo hace muy teórico y no explica muy bien el paso a paso ni como desea que uno resuelva tanto los exámenes como los trabajos.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '556b9af4d3b73f43363b40501d2f592decacb697f34a428979c9958da5787d1f'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'Pésima profesora, no matriculen con ella'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'a52955d37a424d87fd434a6e16ba22b2752e9a545e250365217aeb8f1f4f5ba3'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'aaa5ee6935dc68218cebf0aac2255907c3d24f7f08dd1e68273bc72728c004c4'::TEXT, ARRAY[963, 1728]::BIGINT[]),
    (433::BIGINT, 'Súper buena profe, no entiendo porque con tanta mala fama, es súper buena académicamente y como persona! La recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'f38e6f1825ce3a756fa160a17605ec85356d7ef5107903ac0f3782dbdb4afd1b'::TEXT, ARRAY[1728, 1742, 1743]::BIGINT[]),
    (433::BIGINT, 'Si quiere aprender, meta con ella. Se enfoca mucho en prepararlo a uno para el proyecto de graduación, tanto para el proyecto escrito como para la exposición. Le da uno visión de la carrera, por si está medio perdido. En consulta es donde más se aprende.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'b060c7dacb7de4d87c88117b107f8de8eef7375b32ff2c4f77b3f89f675a3ba2'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Mejor esperar y lo lleva con otro profesor. En clase parece que explica bien porque ya se sabe la materia de memoria, sin embargo, si se pone a resolver un ejercicio nuevo no sabe hacerlo. Los exámenes y quices los busca ya resueltos porque ni ella sabe como hacerlos.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'f87d815062de4392faa9a9434917d671c2a04eca6a7805853009a87d2ca1a238'::TEXT, ARRAY[1728, 1742, 1743]::BIGINT[]),
    (433::BIGINT, 'Es bastante necia pero es solo de hacerle caso. En los proyectos casi que lo único importante es formato y ya pasa. Para los exámenes, solo consiga el del semestre anterior (es igual). En consulta ayuda mucho y se aprende bastante en la clase.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'ba1b40d004aa0d92a1eb13e3e5cf298f86fe3ea9b55780b65a19ce600fc71d83'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'La peor profe que he topado en el TEC, lo digo más que todo como persona, es sumamente hipocrita, le hace creer a uno que es buena persona y a mitad de semestre uno se da cuenta como es. No le gusta pasar las presentaciones por lo que uno debe jugarsela buscando toda la informacion. Califica duro'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2019-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'b2c2e138532d907bdbf5883fabae346eb5c7559a42602b509b6917b3255eb5ad'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'Me parece una excelente profe, la gente le tiene miedo, pero explica muy bien, si tiene dudas ella las atiende (solo en horario de consulta) incluso se aprende demasiado. El curso es pesado, pero no tenga miedo de llevarlo con ella.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-21T00:00:00+00:00'::TIMESTAMPTZ, '11067e46d08721e285df3c7b8cbc68c5a6d21d0806535a24005c0f7875e595fb'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Se aprende demasiado para la vida en los temas del curso, solamente que se vuela en los examenes con trampas y cosas que analizar. Se pierde muy facil ese curso'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-06T00:00:00+00:00'::TIMESTAMPTZ, '92b9ec7e721a0d36b18681fd86bee7ceddc8be8390e5a7a5c67def74b8da59b7'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Sumamante cerrada a su metodología. Muy ortodoxa. A partir como de semana 8, hay trabajos grupales muy grandes todas las semanas. No obstante explica bien y la clase en si no es aburrida. Se aprende pero se sufre de más, no recomendada'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Muchos proyectos grupales']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '45839530e85c120291dad57de2c7916b3ef91471b29a91e85df26fc0b5a729d4'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'La profe es excelente persona, si usted va a consulta y le pone pasa. Eso sí, se aprende a duras penas porque no es muy clara con la materia, incluso se enredaba a veces. Si se puede pasar con ella y ayuda para que los estudiantes pasen.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Exámenes retadores']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '84c0a63e4f666e2886399414179a3bd7f916ce752e0172276f26952032fa7dd0'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Es hipócrita, al principio parece que realmente quiere que usted aprenda, pero va pasando el semestre y usted se da cuenta que lo único que ella quiere es reventarlo en todo y que no pase el curso. Evítela siempre. Los exámenes son una tontería, ni ella los puede hacer sin cometer errores.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'b8ba44b35cac8cf5bc070963bbf7b9eeeb2d0977b751b7e6178b1bcc5d4d318a'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Hasta es mejor atrasarse un semestre que meter con ella Logística o Proba..como persona aparenta ser buena gente...'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'dd3fe10a3e3bb60b2bbd840ed8280312178efdf25a3b095b93aa75943957fb5e'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'Lo que evalúa en exámenes es diferente a los visto en clases. Tiene muchos errores en las diapositivas que nunca corrige. No soporta reclamos de evaluaciones entregadas. No hay claridad en los temas vistos. Nunca apaga el celular y a cada rato la llaman.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '151a2e0d562aa8c9377f3e73f9bd52a459dee14c61b5208537c628526d0c21fa'::TEXT, ARRAY[2474, 1745]::BIGINT[]),
    (433::BIGINT, 'La profe es un amor, pero el curso se vuelve muy difícil con ella, los exámenes son otra cosa a lo que uno ve en clase, es muy duro, si se aprende pero a duras penas'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'b14c30c246288d8f51f3cc68d2e108329a631b569fd824fb76e6ce5e5e1dab27'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'LA PEOR PROFESORA DE LA ESCUELA. DE VERDAD LA PEOR Y NI SIQUIERA TIENE EXPERIENCIA'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'fbd89456b38d1af5f573e94bf10ab1ad6bbc0f6077eff888b7be2f89c1c0e058'::TEXT, ARRAY[1736]::BIGINT[]),
    (433::BIGINT, 'Excelente profesora, se aprende muchísimo. Tiene mucho conocimiento, el cual sabe brindarle al estudiante. Es cuestión de ser muy respetuoso con ella y ponerle desde el principio.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'd9140380a1c6daecb1f95e319a6570deaa9f5eb3f95e21bf794e38677fd3efa0'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Excelente persona y profesora. No apta para mediocres.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2018-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'd91136ea3b1b3757581ff3090066634251a4fd5b7e4cbbc47a41bc7295f88deb'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Muy mala como profesora y me atrevo a decir que como persona, parare que disfruta como el estudiante sufre. Los exámenes no se encuentran al nivel de lo que ve en clase, son muy volados.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2018-01-06T00:00:00+00:00'::TIMESTAMPTZ, '7dbef5bc966118be61f522fe3bcaca0cfd5d12fda19994ff53e25b9b50a6471a'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Una de las mejores profesoras que he tenido en el TEC. Se aprende demasiado, tanto de la materia del curso, como para proyecto de graduación. El truco esta en leerse el libro a conciencia, hacer todos los quices y tener un buen formato en el proyecto y laboratorios.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'ceae98d6d8d17caf0b5f9e83769d744827f59592f0d0d7eb40b296685ec48248'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Hace evaluaciones muy duras y califica igual de duro pero ud aprende demasiado. Si ud lleva la materia al día y va a consulta ud pasa el curso. Yo la recomiendo, solo que póngale en el proyecto porque es súper minuciosa calificándolo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'edde09d2f8a4fed7fc4ce1b415f6373c0cb4dd301b2aaaa663af80892b75bf39'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Buena profe, no es como todos dicen,explica bastante bien, si es estricta con la hora para aplicar y entregar evaluaciones y exámenes largos pero no complicados.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'a60b6a86d5b814d8469c7ff02ab1da36abfe1bf18d70b38947ce893b98962f14'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Le pela si solo pasa 1 persona, hace exámenes muy duros y para pasar hay que matarse desde las primeras semanas e ir a consulta. Me parece que exige más de lo que necesario ya que lo que da se queda muy muy corto en comparación al examen.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, '3f212765e44102ea60e2c1b3953211bc0de3a1bef4d81c09d2932326f7386948'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Siempre tiene la razón, es decir, olvídese de reclamos a menos de que sea que contó mal los puntos. Exámenes súper volados comparado a lo que explicó en clase. CUIDADO le toma una foto en clase porque lo demanda, mucho menos copie porque hace lo que sea para que lo echen del TEC. Paupérrima profe.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2017-06-18T00:00:00+00:00'::TIMESTAMPTZ, '6b2fba981a05fefc4c1d26d43a475bdb7b9ade5d45c65a12963af41e95514d19'::TEXT, ARRAY[963, 1745, 1727, 1736]::BIGINT[]),
    (433::BIGINT, 'Es amable, explica algo bien, no deja tareas (lo cual no ayuda nada) y hace quices matadores, los exámenes complicados (están a otro nivel de lo que ella explica en clase)...Si tiene otra opción o un semestre pesado no matricule con ella; pero si lo decide hacer, vaya a consulta.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '0eb5e4166c729a373885c65dc26d5a4ae976fa06c1f7dc9f563a9ea8d8e6d0b2'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'De verdad, es una descarada, porque no le importa que muchos se queden en este curso. Hace exámenes exageradamente difíciles. Califica muy rudo el proyecto. Y uno comete un plagio, por más pequeño que sea, acude la asamblea para expulsarlo. Así que lo tome en consideración, si matriculan con ella'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-05-27T00:00:00+00:00'::TIMESTAMPTZ, '4206ef6f769d0cf31362dc0f3b31e4518ffa287e5df36ba80c74820a94385b65'::TEXT, ARRAY[2474, 1745]::BIGINT[]),
    (433::BIGINT, 'Es horrible, y si usted le cae mal de fijo no pasa. Vaya a consulta y tratela con mucho respeto porque ella nota mucho eso. Participe en clases y talvez TALVEZ, no se queda. No se recomienda para nada.Si va a repo, despidase.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'e209ff337064c9911babd66faac0399680a432ce210a79a99953ac4b0c06c7ef'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Explica bien en consulta porque está muy bien preparada pero en clase se salta las presentaciones. Sólo llega a leer las PPT (las cuales siempre tienen errores "por corregir"). Siempre sale en clases a contestar llamadas. Si tiene algún reclamo nunca vas a tener la razón.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2017-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'd6f755454078e8fb0dabab12600bc96f5a193d310adb3044280bd147618643ac'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Exámenes retadores']::TEXT[], '2017-01-20T00:00:00+00:00'::TIMESTAMPTZ, '36a55df89438af4a635c1b9a88f9e962a3c6b17dabb6f26dc8658d61986715a6'::TEXT, ARRAY[963, 1728]::BIGINT[]),
    (433::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'ccb06af4e6009cc9dc6cc8e1b6fbaf94a1807fc8bde8c5fbadccb1693a26bf3c'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Puede ser que sepa mucho, pero explica lo mínimo comparado a lo que pregunta en el examen. Califica rudísimo y los enunciados son muy confusos. No la recomiendo para nada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-27T00:00:00+00:00'::TIMESTAMPTZ, '3afac50219ac4e766d631814c918b96f159546fa7c90692d859218a62511b180'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Como profesora sabe mucho, pero explica lo mínimo en clases y en los exámenes el enunciado es confuso para hacer que el estudiante "piense que hacer", haciendo que se pierda el curso no por falta de conocimientos sino por exámenes confusos.Si piensa en ella, ahorrese el tiempo y espere un semestre .'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2016-11-21T00:00:00+00:00'::TIMESTAMPTZ, '63e95f48ddb2647596e8fbd371ffb35a0867d3cea424884b44a4a9e70373eaf2'::TEXT, ARRAY[963, 1728]::BIGINT[]),
    (433::BIGINT, 'Como persona es amable y llevadera, como profesora, apenas regular. Explica bien en clases sin embargo no pasa de explicar lo mínimo, mientras que los exámenes son de otro planeta y es demasiado subjetiva para calificar; califica a matar. La intención no es que uno aprenda sino que le vaya mal.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2016-11-07T00:00:00+00:00'::TIMESTAMPTZ, '737a3b49c9ec16a7679f57747dadeae98823d90bd33ba0d1a869e062ad03df80'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-01T00:00:00+00:00'::TIMESTAMPTZ, '56882e6f2fd1cdf08f0703442b78c9e8478b28930dd35ce4dbefb4b386eea4de'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Excelente persona, CUIDADO con los examenes son muy dificiles, pero si se aprende bastante. Solo hay que "agarrarle el toque" a sus examenes y a su manera de pensar las cosas. Suerte!'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '9c70666690c07b74e32a672d66e7adb69976638f43edd69cf7c8673bf52ea23b'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Es buena gente y explica muy bien dada la experiencia que tiene en ciertos temas. Sin embargo, hace exámenes rudísimos en donde los enunciados pueden resultar confusos y eso propicia que los estudiantes fallen con facilidad. Dicho curso requiere bastante tiempo para estudiar.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '6731e36b97ae4fc75cf1bdce3756070c97a809517f8ac6b3b2bf368c2c083350'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Una profesora traumada, hace los exámenes con la intención de que el estudiante falle, mal redactados. Como persona es excelente y amable, como profesora hay pocas peores. Si encuentra que en el examen fallaste algo mínimo ten pondrá 5/20 pts por ejemplo. Evitarla siempre que se pueda.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'cad318fbc6df94ad062f6e21c1593cb9e3710b81c5ca7eda784b865c7dbc838a'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'Poco accesible en cuanto a reclamos Pregunta en evaluaciones cosas q no se vieron en clase Readaccion enunciados poco clara'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes', 'Exámenes retadores']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'b48f6767f9c35aa39ed95254a65516c31c0b859eaff2fb80e746559959003542'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2016-02-10T00:00:00+00:00'::TIMESTAMPTZ, '19f3b8253ba21e931b56ed902aa8cde1139851dfb4a64bc586f3b042f47a2455'::TEXT, ARRAY[963, 1728]::BIGINT[]),
    (433::BIGINT, 'Debería de existir talleres extras para el curso.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, '2e80f66206f068089c9e0ab4c46a8dcc087c97c989aa1b89d2970def85d65638'::TEXT, ARRAY[1745, 2474]::BIGINT[]),
    (433::BIGINT, 'Como profesora le falta mucho a la hora de explicar. Sabe mucho y se sabe explicar, pero se queda corta en clase. Además llega a ser muy subjetiva a la hora de revisar depende quien es ud (si pasa metido en consulta le va bien, si no practicamente lo hace quedado ya).'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'fcb6150416c0f034949425ebe91a306d862fd373eb80120583bae18654e8bfc4'::TEXT, ARRAY[963, 1728]::BIGINT[]),
    (433::BIGINT, 'Revisa un poco duro y es extricta pero si se estudia si se pasa el curso'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '3729147887cc9a406b2edbd38f306204660425a75d31e345f438a73c0407c8ff'::TEXT, ARRAY[963, 1728]::BIGINT[]),
    (433::BIGINT, 'Se aprende bastante sobre los temas solamente que los exámenes son muy volados y estricta quiere todo perfecto en el proyecto con el mínimo detalle fijo baja puntos. (tamaño letra, sobre manila...) Hay que ser muy disciplinados con el curso!!pero si se logra pasar.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'fd8de4d275dc1a4e750f0e5a3b4d0612f7a86e7d5e1d265391606aaf243497ba'::TEXT, ARRAY[1727]::BIGINT[]),
    (433::BIGINT, 'Califica demasiado rudo los exámenes'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd02722040011ae59b4a66563e661c4675e6225c9c18976270844739b12d46bb0'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Se aprende bastante, su problema es que califica los exámenes demasiado duro, aún cuando usted merece puntos, ella no los dá.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'aed0898644116c1fad39845f64cea661489d6fe6b8aaa29ec900d02cd0a89b64'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Explica muy bien, siempre atiende dudas, pero si hace exámenes un poco duro'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'f3a6aa274410695f501057f904c1134fd0590b6c762ae1e09630ef62b1b36850'::TEXT, ARRAY[963, 1728]::BIGINT[]),
    (433::BIGINT, 'Muy buena gente, aclara hasta las dudas más tontas que se tenga. Fomenta la responsabilidad, ya que de usted depende pasar.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, '20503795b9d7cf81a787883dbe5c9f111c42cc2c167b49d12ccde7fd92466186'::TEXT, ARRAY[1736]::BIGINT[]),
    (433::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-13T00:00:00+00:00'::TIMESTAMPTZ, '1baea2f0ebf299c118dec1f3283ba7f3f5107a9d566d10c1032790cad8e2b8da'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'Es una profesora estricta, pero estamos en el TEC para profes fáciles están las universidades privadas, buena profe, si le pone le pasa, No le regala puntos a nadie, pero si le pide ayuda en explicaciones ella con gusto se la da. Tip para los exámenes: vaya a consulta.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-07T00:00:00+00:00'::TIMESTAMPTZ, 'f496aae9fa90b46f94f2246f1aff8c982f8c8e00d08c423a787a9d6194e0aac7'::TEXT, ARRAY[1728]::BIGINT[]),
