    (433::BIGINT, 'No la recomiendo para nada, explica regular nada del otro mundo, es estricta, hace exámenes confusos; el enunciado nunca es claro además son difíciles, califica terriblemente duro y da la falsa impresión de que es pura vida hahaha'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '029541837fa0a0f353f524244feb4fdc5d72ec5ac3c5e7ba2ea0d12c9d050ce8'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'f498c3de57d87d40aa90071f8755b49ac862595fbd316d10e0b19c3cc603a406'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'No sabe mucho con respecto a lo que exige en los exámenes.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-30T00:00:00+00:00'::TIMESTAMPTZ, '6518694cfea2662cdf1870ac12cf8354318ccf237118786784015d2b013682a2'::TEXT, ARRAY[1728]::BIGINT[]),
    (433::BIGINT, 'LLeve Proba I con ella y cuando llegué a ProbaII me dí cuenta que no había aprendido nada teoría'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, '724f2ddac5d5140291441e1b40c8cd7b8df54a6a8368054a439cdf048c4564d1'::TEXT, ARRAY[963, 1728]::BIGINT[]),
    (433::BIGINT, 'Explica muuy bien, pero hace los examenes muy rudos'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '070d9e0b4b778dff353ed1429444ee4225e3311a7b097e6914a1580aeeccc214'::TEXT, ARRAY[963]::BIGINT[]),
    (433::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'c42d4f60596407394cc1a01c5460a13b2e03e97f3e62df4efcd5cc773fb29237'::TEXT, ARRAY[963, 1728]::BIGINT[]),
    (433::BIGINT, 'Se aprende, pero cuesta mucho aprobar por que los examenes los hace difíciles.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '7eb9cacf31ad6be06ffe748b542a65202ab72cc57bfd03db28fe3a4bdbd5dec4'::TEXT, ARRAY[963, 1728]::BIGINT[]),
    (433::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'fdcae9c4cb6000dcc3333aa15b9382b78d3cc5a388864c9b6c1899851365f95e'::TEXT, ARRAY[963]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
